# Let's look at the differences more carefully
inputs = ['xi', 'xf', 'bycvf', 'diuwx', 'euyfk']
outputs = ['ci', 'cf', 'byiifvf', 'diudc', 'euyfk']

# Analyze each transformation
print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input: '{inp}' -> Output: '{out}'")
    if inp != out:
        # Find what changed
        if len(inp) == len(out):
            # Same length - character substitution
            for j, (ch_in, ch_out) in enumerate(zip(inp, out)):
                if ch_in != ch_out:
                    print(f"  Position {j}: '{ch_in}' -> '{ch_out}'")
        elif len(inp) > len(out):
            # Length decreased - deletion
            print(f"  Deleted characters")
        else:
            # Length increased - insertion
            print(f"  Inserted characters")
    else:
        print("  No change")
    print()

